//! A painted sample landscape, so the app has something to grade before a
//! photo is opened. It is generated by code; no picture file is involved.

use crate::pipeline::Picture;
use rayon::prelude::*;

fn hash(x: i32, y: i32) -> f32 {
    let mut h = (x as u32).wrapping_mul(0x9E37_79B1) ^ (y as u32).wrapping_mul(0x85EB_CA77);
    h ^= h >> 15;
    h = h.wrapping_mul(0xC2B2_AE3D);
    h ^= h >> 13;
    (h & 0xFFFF) as f32 / 65535.0
}

fn noise(x: f32, y: f32) -> f32 {
    let (ix, iy) = (x.floor() as i32, y.floor() as i32);
    let (tx, ty) = (x - x.floor(), y - y.floor());
    let (sx, sy) = (tx * tx * (3.0 - 2.0 * tx), ty * ty * (3.0 - 2.0 * ty));
    let a = hash(ix, iy) + (hash(ix + 1, iy) - hash(ix, iy)) * sx;
    let b = hash(ix, iy + 1) + (hash(ix + 1, iy + 1) - hash(ix, iy + 1)) * sx;
    a + (b - a) * sy
}

fn fbm(x: f32, y: f32, octaves: u32) -> f32 {
    let (mut s, mut amp, mut f, mut norm) = (0.0, 0.5, 1.0, 0.0);
    for _ in 0..octaves {
        s += noise(x * f, y * f) * amp;
        norm += amp;
        amp *= 0.5;
        f *= 2.03;
    }
    s / norm
}

fn lerp3(a: [f32; 3], b: [f32; 3], t: f32) -> [f32; 3] {
    let t = t.clamp(0.0, 1.0);
    [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]
}

fn smooth(a: f32, b: f32, x: f32) -> f32 {
    let t = ((x - a) / (b - a)).clamp(0.0, 1.0);
    t * t * (3.0 - 2.0 * t)
}

fn ridge(x: f32, seed: f32, base: f32, height: f32) -> f32 {
    let n = fbm(x * 3.2 + seed, seed * 1.7, 6);
    let r = 1.0 - (2.0 * n - 1.0).abs();
    base - r * r * height
}

fn sky(u: f32, v: f32) -> [f32; 3] {
    let top = [0.27, 0.46, 0.68];
    let low = [0.93, 0.74, 0.55];
    let mut c = lerp3(top, low, smooth(0.0, 0.5, v));
    let (dx, dy) = ((u - 0.68) * 1.5, v - 0.42);
    let d = (dx * dx + dy * dy).sqrt();
    c = lerp3(c, [1.0, 0.92, 0.72], (0.7 - d * 2.4).max(0.0));
    let clouds = smooth(0.5, 0.74, fbm(u * 4.0 + 2.0, v * 9.0, 6));
    let lit = smooth(0.3, 0.75, fbm(u * 7.0 + 9.0, v * 14.0, 4));
    lerp3(c, lerp3([0.74, 0.72, 0.78], [1.0, 0.9, 0.82], lit), clouds * 0.86)
}

fn color_at(u: f32, v: f32) -> [f32; 3] {
    let waterline = 0.665;
    let (uu, vv, reflected) = if v > waterline && v < 0.86 {
        (u + (fbm(u * 3.0, v * 90.0, 2) - 0.5) * 0.018, waterline - (v - waterline) * 1.3, true)
    } else {
        (u, v, false)
    };
    let far = ridge(uu, 3.1, 0.55, 0.2);
    let mid = ridge(uu, 7.7, 0.62, 0.21);
    let near = ridge(uu, 12.4, 0.68, 0.13);

    let mut c = sky(uu, vv);
    if vv > far {
        let shade = fbm(uu * 18.0, vv * 18.0, 5);
        c = lerp3([0.46, 0.5, 0.64], [0.72, 0.68, 0.72], shade);
    }
    if vv > mid {
        let shade = fbm(uu * 26.0 + 4.0, vv * 26.0, 5);
        c = lerp3([0.19, 0.3, 0.33], [0.42, 0.45, 0.38], shade);
    }
    if vv > near {
        let shade = fbm(uu * 40.0 + 8.0, vv * 40.0, 5);
        c = lerp3([0.07, 0.16, 0.12], [0.2, 0.32, 0.15], shade);
    }
    if reflected {
        let depth = smooth(waterline, 0.86, v);
        c = lerp3(c, [0.08, 0.22, 0.3], 0.26 + depth * 0.5);
        let glint = smooth(0.62, 0.8, fbm(u * 26.0, v * 240.0, 3)) * (1.0 - ((u - 0.68) * 5.0).abs()).max(0.0);
        c = lerp3(c, [1.0, 0.9, 0.7], glint * 0.8);
    }
    if v > 0.82 {
        // Foreground meadow with scattered flowers.
        let edge = 0.815 + (fbm(u * 8.0, 2.0, 4) - 0.5) * 0.05;
        if v > edge {
            let shade = fbm(u * 70.0, v * 34.0, 5);
            let depth = smooth(edge, 1.0, v);
            c = lerp3(lerp3([0.42, 0.5, 0.17], [0.76, 0.72, 0.28], shade), [0.12, 0.25, 0.09], depth * 0.75);
            let size = 34.0 + (1.0 - depth) * 80.0;
            let (fx, fy) = (u * size * 1.5, v * size);
            let (ix, iy) = (fx.floor() as i32, fy.floor() as i32);
            let on = hash(ix, iy);
            if on > 0.72 {
                let (cx, cy) = (hash(ix + 5, iy) * 0.6 + 0.2, hash(ix, iy + 5) * 0.6 + 0.2);
                let (dx, dy) = (fx - ix as f32 - cx, fy - iy as f32 - cy);
                let bloom = smooth(0.2, 0.06, (dx * dx + dy * dy).sqrt());
                let petal = if on > 0.92 { [0.98, 0.93, 0.9] } else if on > 0.82 { [0.97, 0.72, 0.16] } else { [0.84, 0.13, 0.12] };
                c = lerp3(c, petal, bloom);
            }
        }
    }
    c
}

pub fn sample_picture(w: usize, h: usize) -> Picture {
    let mut px = vec![[0.0f32; 3]; w * h];
    px.par_chunks_mut(w).enumerate().for_each(|(y, row)| {
        for (x, o) in row.iter_mut().enumerate() {
            let (u, v) = ((x as f32 + 0.5) / w as f32, (y as f32 + 0.5) / h as f32);
            let u2 = u * w as f32 / h as f32 * 0.667;
            *o = color_at(u2, v);
        }
    });
    Picture { w, h, px }
}
